"use client";

import { useEffect, useState } from "react";
import { useGetChat, useSendMessage } from "@/hooks/use-chat";
import { Button } from "@/components/ui/button";
import { Sparkles, User, Copy, RefreshCw } from "lucide-react";
import { cn } from "@/lib/utils";
import { useRouter } from "next/navigation";

// prompt-kit components
import {
    ChatContainerRoot,
    ChatContainerContent
} from "@/components/prompt-kit/chat-container";
import {
    Message,
    MessageAvatar,
    MessageContent,
    MessageActions,
    MessageAction
} from "@/components/prompt-kit/message";
import {
    PromptInput,
    PromptInputTextarea,
    PromptInputActions,
    PromptInputAction
} from "@/components/prompt-kit/prompt-input";
import { Loader } from "@/components/prompt-kit/loader";

interface ChatContainerProps {
    chatId: string;
}

export function ChatContainer({ chatId }: ChatContainerProps) {
    const chat = useGetChat(chatId);
    const sendMessageMutation = useSendMessage();
    const [inputValue, setInputValue] = useState("");
    const router = useRouter();

    const messages = chat?.messages || [];

    const handleSendMessage = () => {
        if (!inputValue.trim()) return;
        sendMessageMutation.mutate({ chatId, content: inputValue });
        setInputValue("");
    };

    if (!chat) {
        return (
            <div className="flex items-center justify-center h-full text-muted-foreground">
                <Loader variant="dots" />
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full bg-background relative overflow-hidden">
            {/* Thread Title Bar */}
            <header className="flex items-center justify-between px-6 py-3 border-b border-border/50 bg-background/80 backdrop-blur-md sticky top-0 z-20">
                <div className="flex items-center gap-3 min-w-0">
                    <div className="bg-primary/10 p-2 rounded-lg shrink-0">
                        <Sparkles className="size-4 text-primary" />
                    </div>
                    <div className="flex flex-col min-w-0">
                        <h1 className="text-sm font-semibold truncate">
                            {chat.title}
                        </h1>
                        <p className="text-[10px] text-muted-foreground">
                            {messages.length} messages
                        </p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" className="size-8 rounded-lg">
                        <User className="size-4" />
                    </Button>
                </div>
            </header>

            {/* Messages Area using chat-container */}
            <ChatContainerRoot className="flex-1 min-h-0 px-4 py-8 scrollbar-hide">
                <ChatContainerContent className="max-w-3xl mx-auto w-full gap-6">
                    {messages.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-[50vh] text-center space-y-4">
                            <div className="bg-primary/10 p-4 rounded-full">
                                <Sparkles className="size-8 text-primary" />
                            </div>
                            <h2 className="text-2xl font-bold">How can I help you today?</h2>
                            <p className="text-muted-foreground max-w-sm">
                                Ask me anything about our products, store locations, or order status.
                            </p>
                            <Loader variant="typing" size="lg" className="opacity-50" />
                        </div>
                    ) : (
                        messages.map((message, index) => (
                            <Message
                                key={index}
                                className={cn(
                                    "w-full",
                                    message.role === "user" ? "flex-row-reverse" : "flex-row"
                                )}
                            >
                                <MessageAvatar
                                    src={message.role === "user" ? "" : "/bot-avatar.png"}
                                    fallback={message.role === "user" ? "U" : "AI"}
                                    alt={message.role}
                                    className="bg-primary/10"
                                />
                                <div className={cn("flex flex-col max-w-[85%]", message.role === "user" ? "items-end" : "items-start")}>
                                    <MessageContent
                                        markdown
                                        className={cn(
                                            "shadow-sm transition-all duration-300",
                                            message.role === "user"
                                                ? "bg-primary text-primary-foreground rounded-tr-none"
                                                : message.content.startsWith("🚨")
                                                    ? "bg-destructive/10 text-destructive rounded-tl-none border-destructive/20 border"
                                                    : "bg-muted text-foreground rounded-tl-none"
                                        )}
                                    >
                                        {message.content === "" ? (
                                            <div className="flex items-center gap-2 px-2 py-1">
                                                <Loader variant="typing" size="sm" />
                                                <span className="text-xs opacity-70">Thinking...</span>
                                            </div>
                                        ) : (
                                            message.content.replace("🚨", "").trim()
                                        )}
                                    </MessageContent>

                                    {/* Message Actions (Only show for assistant for now) */}
                                    {message.role === "assistant" && message.content !== "" && (
                                        <MessageActions className="mt-1 ml-1">
                                            <MessageAction
                                                tooltip="Copy text"
                                                onClick={() => navigator.clipboard.writeText(message.content)}
                                            >
                                                <Copy className="size-3" />
                                            </MessageAction>
                                            <MessageAction tooltip="Regenerate">
                                                <RefreshCw className="size-3" />
                                            </MessageAction>
                                        </MessageActions>
                                    )}

                                    <span className="text-[10px] text-muted-foreground mt-1 px-1">
                                        {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </span>
                                </div>
                            </Message>
                        ))
                    )}
                </ChatContainerContent>
            </ChatContainerRoot>

            {/* Input Area using prompt-input */}
            <div className="p-4 bg-background/95 backdrop-blur-sm border-t border-border/50">
                <div className="max-w-3xl mx-auto">
                    <PromptInput
                        value={inputValue}
                        onValueChange={setInputValue}
                        onSubmit={handleSendMessage}
                        isLoading={sendMessageMutation.isPending}
                        className="border-primary/20 focus-within:ring-2 ring-primary/20 transition-all shadow-md"
                    >
                        <PromptInputTextarea
                            placeholder="Message AI Assistant..."
                            disableAutosize={false}
                            className="text-base sm:text-sm"
                        />
                        <PromptInputActions className="justify-end px-2 pb-2">
                            <PromptInputAction tooltip="Send Message">
                                <Button
                                    size="icon"
                                    variant="ghost"
                                    className={cn(
                                        "size-8 rounded-full transition-all",
                                        inputValue.trim() ? "bg-primary text-primary-foreground hover:bg-primary/90" : "bg-muted text-muted-foreground"
                                    )}
                                    onClick={handleSendMessage}
                                    disabled={!inputValue.trim()}
                                >
                                    <Sparkles className="size-4" />
                                </Button>
                            </PromptInputAction>
                        </PromptInputActions>
                    </PromptInput>
                    <p className="text-[10px] text-center mt-3 text-muted-foreground font-medium uppercase tracking-wider opacity-60">
                        Powered by LLM Chat Engine
                    </p>
                </div>
            </div>
        </div>
    );
}
