"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"
import { cn } from "@/lib/utils"

interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
    children: React.ReactNode
}

export function CodeBlock({ children, className, ...props }: CodeBlockProps) {
    return (
        <div className={cn("relative overflow-hidden rounded-lg border bg-background", className)} {...props}>
            {children}
        </div>
    )
}

export function CodeBlockCode({ code, language }: { code: string; language: string }) {
    const [copied, setCopied] = React.useState(false)

    const copyToClipboard = async () => {
        await navigator.clipboard.writeText(code)
        setCopied(true)
        setTimeout(() => setCopied(false), 2000)
    }

    return (
        <div className="relative group">
            <div className="flex items-center justify-between px-4 py-2 bg-muted border-b">
                <span className="text-xs font-medium text-muted-foreground uppercase">{language}</span>
                <button
                    onClick={copyToClipboard}
                    className="p-1 hover:bg-background rounded-md transition-colors"
                    title="Copy code"
                >
                    {copied ? (
                        <Check className="size-3.5 text-green-500" />
                    ) : (
                        <Copy className="size-3.5 text-muted-foreground" />
                    )}
                </button>
            </div>
            <pre className="p-4 overflow-x-auto text-sm bg-[#0d1117] text-gray-100 font-mono">
                <code className={`language-${language}`}>{code}</code>
            </pre>
        </div>
    )
}
